366	    /** Set the sheet's parent (null: none), the sheet created first if it was never loaded; not
367	     *  dated, a grade with no rate of its own in force on a date takes the parent's (then its
368	     *  parent's, up to three levels up), so every live due (and every total) moves with it. Refused
369	     *  (422) when it is the sheet itself, a sheet never loaded, or one with this sheet as an ancestor. */
370	    @Transactional
371	    public String setParent(String sheetId, String user, String parent) {
372	        Sheet sheet = sheets.load(sheetId, user);
373	        sheets.lock(sheetId);
374	        if (parent != null) {
375	            if (parent.equals(sheetId)) {
376	                throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, "A sheet cannot be its own parent");
377	            }
378	            if (sheets.find(parent).isEmpty()) {
379	                throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, "No sheet " + parent + " has been loaded");
380	            }
381	            Set<String> seen = new HashSet<>();
382	            for (String at = parent; at != null && seen.add(at); at = sheets.find(at).map(Sheet::getParent).orElse(null)) {
383	                if (at.equals(sheetId)) {
384	                    throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
385	                            "The sheet " + parent + " has this sheet as an ancestor");
386	                }
387	            }
388	        }
389	        RollupService.Snapshot before = rollup.snapshot(sheetId);
390	        sheet.setParent(parent);
391	        sheets.flush();
392	        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user
393	                + " key=" + PARENT + " value=" + (parent == null ? "" : parent));
394	        rollup.recordChanges(sheetId, user, before);
395	        return parent;
396	    }
