486	    /** The steward whose delegation the user name acts under on the sheet's today; null when it
487	     *  acts in its own right (a steward itself, or no delegation covers the sheet's today). */
488	    @Transactional(readOnly = true)
489	    public String delegatorOf(String sheetId, String user) {
490	        List<SheetDelegation> made = delegations.findBySheetIdAndUserOrderByIdDesc(sheetId, user);
491	        if (made.isEmpty() || heldRoleOf(sheetId, user) == Role.STEWARD) {
492	            return null;
493	        }
494	        LocalDate today = sheets.today(sheetId);
495	        return made.stream().filter(d -> d.covers(today)).map(SheetDelegation::getSteward).findFirst().orElse(null);
496	    }
