498	    @Transactional(readOnly = true)
499	    public List<SheetDelegation> delegations(String sheetId) {
500	        return delegations.findBySheetIdOrderByIdAsc(sheetId);
501	    }
502	
503	    /** Delegate the steward role to a user name from a date (null: the sheet's today) to a date
504	     *  (null: the from-date), inclusive, the sheet created first if it was never loaded; refused
505	     *  (403) unless the user is a steward in its own right, and (400) for a to-date before the
506	     *  from-date. */
507	    @Transactional
508	    public SheetDelegation delegate(String sheetId, String user, String name, LocalDate from, LocalDate to) {
509	        sheets.load(sheetId, user);
510	        if (heldRoleOf(sheetId, user) != Role.STEWARD) {
511	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward may delegate");
512	        }
513	        LocalDate start = from == null ? sheets.today(sheetId) : from;
514	        LocalDate end = to == null ? start : to;
515	        if (end.isBefore(start)) {
516	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The to-date is before the from-date");
517	        }
518	        SheetDelegation made = delegations.saveAndFlush(new SheetDelegation(sheetId, name, user, start, end));
519	        audit.recordOnCommit("DELEGATED sheet=" + sheetId + " by=" + user + " user=" + name
520	                + " from=" + start + " to=" + end);
521	        return made;
522	    }
