524	    /** The sheet's holidays, earliest first. */
525	    @Transactional(readOnly = true)
526	    public List<LocalDate> holidays(String sheetId) {
527	        return holidays.findBySheetIdOrderByDayAsc(sheetId).stream().map(SheetHoliday::getDay).toList();
528	    }
529	
530	    /** Add a holiday to the sheet, the sheet created first if it was never loaded; refused (409)
531	     *  when the date is on its list already. {@link HolidayAdded} is published once it is on the
532	     *  list, re-fixing the due-by of the claims due on or after it. */
533	    @Transactional
534	    public LocalDate addHoliday(String sheetId, String user, LocalDate day) {
535	        sheets.load(sheetId, user);
536	        sheets.lock(sheetId);
537	        if (holidays.existsBySheetIdAndDay(sheetId, day)) {
538	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The date is a holiday already");
539	        }
540	        holidays.saveAndFlush(new SheetHoliday(sheetId, day));
541	        audit.recordOnCommit("HOLIDAY_ADDED sheet=" + sheetId + " by=" + user + " date=" + day);
542	        events.publishEvent(new HolidayAdded(sheetId, user, day));
543	        return day;
544	    }
