546	    /** The sheet's void reasons, in the order they were added. */
547	    @Transactional(readOnly = true)
548	    public List<String> voidReasons(String sheetId) {
549	        return voidReasons.findBySheetIdOrderByIdAsc(sheetId).stream().map(SheetVoidReason::getReason).toList();
550	    }
551	
552	    /** Whether the reason is on the sheet's list of void reasons. */
553	    @Transactional(readOnly = true)
554	    public boolean isVoidReason(String sheetId, String reason) {
555	        return voidReasons.existsBySheetIdAndReason(sheetId, reason);
556	    }
557	
558	    /** Add a void reason to the sheet, the sheet created first if it was never loaded; refused (409)
559	     *  when the reason is on its list already. */
560	    @Transactional
561	    public String addVoidReason(String sheetId, String user, String reason) {
562	        sheets.load(sheetId, user);
563	        sheets.lock(sheetId);
564	        if (voidReasons.existsBySheetIdAndReason(sheetId, reason)) {
565	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The reason is on the list already");
566	        }
567	        voidReasons.saveAndFlush(new SheetVoidReason(sheetId, reason));
568	        audit.recordOnCommit("VOID_REASON_ADDED sheet=" + sheetId + " by=" + user + " reason=" + reason);
569	        return reason;
570	    }
571	
572	    /** Archive the sheet, the sheet created first if it was never loaded; refused (403) unless the
573	     *  user acts as a steward, and (409) when it is archived already. */
574	    @Transactional
575	    public Sheet archive(String sheetId, String user) {
576	        Sheet sheet = sheets.load(sheetId, user);
577	        sheets.lock(sheetId);
578	        if (roleOf(sheetId, user) != Role.STEWARD) {
579	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward may archive the sheet");
580	        }
581	        if (sheet.isArchived()) {
582	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The sheet is archived already");
583	        }
584	        sheet.archive();
585	        sheets.flush();
586	        audit.recordOnCommit("SHEET_ARCHIVED sheet=" + sheetId + " by=" + user);
587	        return sheet;
588	    }
589	
590	    /** Whether the user name is a viewer on the sheet: sees it and may change nothing on it. */
591	    @Transactional(readOnly = true)
592	    public boolean isViewer(String sheetId, String user) {
593	        return roleOf(sheetId, user) == Role.VIEWER;
594	    }
595	
596	    /** Give a user name a role on the sheet, the sheet created first if it was never loaded. */
597	    @Transactional
598	    public SheetRole setRole(String sheetId, String user, String name, Role role) {
599	        sheets.load(sheetId, user);
600	        SheetRole held = roles.findBySheetIdAndUser(sheetId, name).orElse(null);
601	        try {
602	            if (held == null) {
603	                held = roles.saveAndFlush(new SheetRole(sheetId, name, role));
604	            } else {
605	                held.setRole(role);
606	                roles.flush();
607	            }
608	        } catch (DataIntegrityViolationException e) {
609	            // set by another user at the same moment
610	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Role changed at the same moment");
611	        }
612	        audit.recordOnCommit("ROLE_SET sheet=" + sheetId + " by=" + user + " user=" + name + " role=" + role.key());
613	        return held;
614	    }
615	
616	    /** Whether a user may settle a claim showing a due (null: n/a, within any limit): a steward
617	     *  settles anything, a clerk only a due at or below the sheet's clerk limit, if it has one. */
618	    @Transactional(readOnly = true)
619	    public boolean maySettle(String sheetId, String user, BigDecimal due) {
620	        if (due == null || roleOf(sheetId, user) == Role.STEWARD) {
621	            return true;
622	        }
623	        BigDecimal limit = clerkLimit(sheetId);
624	        return limit == null || due.compareTo(limit) <= 0;
625	    }
626	
627	    /** The roles the sheet's permission matrix sets for each action, as set; an action left blank
628	     *  (keeping its standing rule) is left out. */
629	    @Transactional(readOnly = true)
630	    public Map<Permission, String> permissions(String sheetId) {
631	        Map<Permission, String> out = new EnumMap<>(Permission.class);
632	        permissions.findBySheetId(sheetId).forEach(p -> out.put(p.getAction(), p.getRoles()));
633	        return out;
634	    }
635	
636	    /** Set the roles that may take an action (blank: its standing rule), comma separated, the
637	     *  sheet created first if it was never loaded; not dated, it applies from now on. */
638	    @Transactional
639	    public String setPermission(String sheetId, String user, Permission action, String rolesText) {
640	        sheets.load(sheetId, user);
641	        sheets.lock(sheetId);
642	        SheetPermission held = permissions.findBySheetIdAndAction(sheetId, action.key()).orElse(null);
643	        if (rolesText.isEmpty()) {
644	            if (held != null) {
645	                permissions.delete(held);
646	            }
647	        } else if (held == null) {
648	            permissions.save(new SheetPermission(sheetId, action, rolesText));
649	        } else {
650	            held.setRoles(rolesText);
651	        }
652	        permissions.flush();
653	        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user
654	                + " key=" + PERMISSION + action.key() + " value=" + rolesText);
655	        return rolesText;
656	    }
657	
658	    /** Whether the user's role may take the action: as the permission matrix sets it, else by its
659	     *  standing rule. */
660	    @Transactional(readOnly = true)
661	    public boolean mayTake(String sheetId, String user, Permission action) {
662	        Role role = roleOf(sheetId, user);
663	        return permissions.findBySheetIdAndAction(sheetId, action.key())
664	                .map(p -> p.roleSet().contains(role))
665	                .orElseGet(() -> action.standing().contains(role));
666	    }
667	
668	    /** Refuse (403) the action unless the user's role may take it. */
669	    @Transactional(readOnly = true)
670	    public void refuseUnlessAllowed(String sheetId, String user, Permission action) {
671	        if (!mayTake(sheetId, user, action)) {
672	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
673	                    "The user's role may not " + action.key() + " on this sheet");
674	        }
675	    }
676	}
